/** Run from desktop/: npx vite-node scripts/engineering/export-review-trees.ts
 * Requires verified raw sources and bounds generated by web-ifc. No sample is
 * modified. Source SHA and source-parser digest are checked before reuse. */
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {resolve,join} from 'node:path';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {unpackEngineeringSource} from '../../src/services/engineeringSourceCodec.js';
import type {EngineeringSourceGraph} from '../../src/gim/engineering/sourceGraph.js';
import {SubstationSpatialIndexBuilder} from '../../src/gim/ifcSpatialParser.js';
import {createIfcModelId} from '../../src/gim/modelIdentity.js';
import {buildEngineeringSources} from '../../src/gim/engineering/buildSources.js';
import {projectEngineeringNavigation} from '../../src/gim/engineering/navigation.js';
import {projectEngineeringComposition} from '../../src/engineering/composition.js';
import {projectSpatialComposition,type CompositionBounds} from '../../src/engineering/compositionSpatial.js';
import {assertEngineeringNavigation} from '../../src/services/engineeringNavigationCache.js';
const root=resolve('..'),out=join(root,'research/reviews/2026-11-03/model-tree');mkdirSync(out,{recursive:true});
const manifest=JSON.parse(readFileSync(join(root,'output/refactor-baseline/manifest.json'),'utf8'));
const hash=createHash('sha256');for(const file of ['src/gim/engineering/sourceGraph.ts','src/gim/famParser.ts','src/gim/gimValueSemantics.ts'])hash.update(file).update(readFileSync(resolve(file)));
const graphDigest=hash.digest('hex'),results=[];
for(const item of manifest.packages){
  const sample=item.sample;if(process.env.GIM_REVIEW_SAMPLE&&sample!==process.env.GIM_REVIEW_SAMPLE)continue;
  const sha=createHash('sha256').update(readFileSync(join(root,item.source.path))).digest('hex');if(sha!==item.source.sha256)throw Error(`${sample}: source SHA mismatch`);
  const saved=unpackEngineeringSource(JSON.parse(gunzipSync(readFileSync(join(root,`output/refactor-navigation-v1/${sample}-source-graph.json.gz`))).toString('utf8'))) as {sourceSha256:string;graphParserSha256:string;graph:EngineeringSourceGraph};
  if(saved.sourceSha256!==sha||saved.graphParserSha256!==graphDigest)throw Error(`${sample}: source graph identity mismatch`);
  const raw=join(root,`output/entity-normalization/source-v1/${sample}/source`),builder=new SubstationSpatialIndexBuilder(null);
  for(const path of saved.graph.ifcPaths)builder.addIfcModel({modelId:createIfcModelId(path),path,name:path},readFileSync(join(raw,path),'utf8'));
  const spatial=builder.finalize(),built=buildEngineeringSources(sha,saved.graph,spatial.objects,spatial.models,spatial.nodes);
  const view=projectEngineeringNavigation(built.sources,built.snapshot),owners=new Map(built.snapshot.memberships.map(m=>[m.sourceId,m.ownerId]));
  const bounds:CompositionBounds[]=[];
  const geometric=JSON.parse(readFileSync(join(root,`output/${sample}-ifc-bounds.json`),'utf8'));
  if(geometric.length!==saved.graph.ifcPaths.length)throw Error(`${sample}: geometry manifest mismatch`);
  for(const model of geometric)if(!saved.graph.ifcPaths.includes(model.path)||model.sha256!==createHash('sha256').update(readFileSync(join(raw,model.path))).digest('hex'))throw Error(`${sample}: stale IFC bounds`);
  for(const model of geometric)for(const object of model.objects){const sourceId=`ifc:${JSON.stringify([createIfcModelId(model.path),object.expressId])}`,owner=owners.get(sourceId);if(owner)bounds.push({entityId:owner,bounds:object.bounds,evidence:sourceId});}
  const diagnostics={footprints:[]},input=view.compositionInput!,assignments=projectSpatialComposition(built.snapshot,input.facts,bounds,diagnostics);
  view.composition=projectEngineeringComposition(built.snapshot,assignments,'工程组成',input.declarations);assertEngineeringNavigation(view,built.sources,built.snapshot);
  // Review output omits repeated path keys/parent pointers. Every row and real
  // entity ID is retained. The app's export still contains the complete wire tree.
  const visit=(key:string):unknown=>{const node=view.composition.nodes.get(key)!;return {title:node.title,kind:node.kind,...(node.targetId?{targetId:node.targetId}:{}),entityCount:node.entityCount,...(node.kind==='group'&&node.evidence.length?{evidence:node.evidence.filter(e=>!e.startsWith('entity:'))}:{}),children:node.children.map(visit)};};
  writeFileSync(join(out,`${sample}-composition.json`),JSON.stringify({schema:'gim-engineering-composition-review-v1',sample,sourceSha256:sha,metadata:view.metadata,root:visit(view.composition.rootKey)},null,2));
  const groups=[...view.composition.nodes.values()].filter(n=>n.kind==='group');
  const buildings=groups.filter(n=>n.key.split('/').at(-1)?.startsWith('building:')).map(n=>({name:n.title,entityCount:n.entityCount}));
  const mains=built.snapshot.entities.filter(e=>e.category==='E01').map(e=>({name:e.name,sourceCount:e.sourceIds.length,roots:saved.graph.records.filter(r=>!r.parent&&e.sourceIds.includes(r.id)).map(r=>({name:r.name,type:r.source_type}))}));
  const row={sample,sourceSha256:sha,graphParserSha256:graphDigest,rulesVersion:built.snapshot.rulesVersion,sourceVersion:built.sources.version,navigationVersion:view.version,sourceComplete:built.sources.complete,incompleteReasons:built.sources.incompleteReasons,outwardSources:built.snapshot.memberships.length,entities:built.snapshot.entities.length,pending:built.snapshot.pending.length,geometryBounds:bounds.length,buildings,mains,wrongMainCabinets:built.snapshot.entities.filter(e=>e.category==='E01'&&/柜|屏/.test(e.name)).length};
  writeFileSync(join(out,`${sample}-checks.json`),JSON.stringify({...row,diagnostics},null,2));results.push(row);console.log(JSON.stringify(row));
}
writeFileSync(join(out,process.env.GIM_REVIEW_SAMPLE?'partial-manifest.json':'manifest.json'),JSON.stringify({complete:results.length===9,scope:'all outward DEV/IFC sources; actual IFC geometry for composition only; classification requires engineering review',results},null,2));
